import type { SlimDeal } from '../../../shared/types.js';
// Generated by `npm run import:deals`. Bundled into the Worker, so it is never publicly downloadable.
import deals from '../data/deals.json';
import { createApp } from './app.js';
import { createDataset } from './dataset.js';

// Built once per Worker isolate and reused by every request it serves.
const dataset = createDataset(deals as unknown as SlimDeal[]);

export default createApp(dataset);
